  'openAccessPolicy' => 
  array (
    'es_AR' => '<p>Esta revista provee acceso libre inmediato a su contenido bajo el principio de  hacer disponible gratuitamente la investigación al público, lo cual fomenta un mayor intercambio de conocimiento global.</p><p>Los trabajos remitidos tendrán una publicación gratuita para los autores.</p>',
